import { chromium } from "playwright";
const CHROMIUM_PATH = "/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium";

const html = `<!doctype html><html><head><style>
  html,body{margin:0}
  .viewport{width:320px;height:568px;position:relative;overflow:hidden}
  .screen{position:absolute;inset:0;display:grid;grid-template-rows:minmax(184px,191px) minmax(246px,1fr);overflow:hidden}
  .hero{background:#eee}
  .panel{
    min-height:0;
    container-type:size;
    background:#049;
    padding-top:24px;
    padding-bottom:76px;      /* dock reservation stand-in */
    display:flex;flex-direction:column;
    /* SELF-REFERENCE: does 100cqh here mean the panel, or an ancestor? */
    --kp-self: calc(100cqh);
  }
  .body{flex:1;min-height:0;overflow-y:auto;
    /* DESCENDANT: this is the legal place */
    --kp-desc: calc(100cqh);
    --kp-size: min(76px, calc((100cqh - 3 * 12px - 2 * 24px) / 4));
    --kp-size-nopad: min(76px, calc((100cqh - 3 * 12px) / 4));
  }
  .key{width:var(--kp-size);height:var(--kp-size);background:#5af;border-radius:999px}
</style></head><body>
<div class="viewport"><div class="screen">
  <div class="hero"></div>
  <div class="panel"><div class="body"><div class="key" id="k"></div></div></div>
</div></div>
</body></html>`;

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
const page = await browser.newPage({ viewport: { width: 320, height: 568 } });
await page.setContent(html);
const out = await page.evaluate(() => {
  const panel = document.querySelector(".panel");
  const body  = document.querySelector(".body");
  const key   = document.getElementById("k");
  const cs = (el, p) => getComputedStyle(el).getPropertyValue(p).trim();
  return {
    panelRect: panel.getBoundingClientRect().height,
    panelContentBox: panel.clientHeight - 24 - 76,
    bodyRect: body.getBoundingClientRect().height,
    kp_self_on_container: cs(panel, "--kp-self"),
    kp_desc_on_child: cs(body, "--kp-desc"),
    kp_size: cs(body, "--kp-size"),
    kp_size_nopad: cs(body, "--kp-size-nopad"),
    keyBox: key.getBoundingClientRect().height,
    containerType: getComputedStyle(panel).containerType,
  };
});
console.log(JSON.stringify(out, null, 2));
await browser.close();
EOF
