import { chromium } from "playwright";
const CHROMIUM_PATH = "/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium";
const VIEWPORTS = [[320,568],[360,640],[375,667],[390,844],[412,915],[430,932]];
const DOCK_H = 64;   // collapsed, Phase D

const html = `<!doctype html><html><head><style>
  @property --probe { syntax: "<length>"; inherits: false; initial-value: 0px; }
  html,body{margin:0;height:100%}
  .tp-viewport{
    width:100%;max-width:430px;height:100svh;margin:0 auto;position:relative;overflow:hidden;
    container-type:inline-size;
    --u: clamp(3.3px, 1.0256cqi, 4px);
    --sp-3: calc(3 * var(--u));
    --sp-6: calc(6 * var(--u));
    --sp-7: calc(7 * var(--u));
    --hero-min:184px;
    --hero-pref: clamp(184px, 33.65svh, 316px);
    --panel-min: calc(4 * 44px + 3 * var(--sp-3) + 2 * var(--sp-6));
    --dock-h: ${DOCK_H}px;
    --safe-bottom: 0px;
    --panel-top: var(--sp-6);
  }
  .tp-screen{position:absolute;inset:0;display:flex;flex-direction:column;overflow:hidden}
  .tp-screen.tp-feature{
    display:grid;
    grid-template-rows: minmax(var(--hero-min), var(--hero-pref)) minmax(var(--panel-min), 1fr);
    overflow:hidden;
  }
  .tp-hero{background:#f4f4f4;min-height:0}
  .tp-panel{
    min-height:0; container-type:size; background:#040D6D;
    display:flex;flex-direction:column;
    padding: var(--panel-top) var(--sp-7) calc(var(--dock-h) + var(--safe-bottom) + var(--sp-3));
    --probe-WRONG: min(76px, calc((100cqh - 3 * var(--sp-3) - 2 * var(--sp-6)) / 4));
  }
  .tp-panel-body{
    flex:1;min-height:0;overflow-y:auto;overscroll-behavior:contain;
    --kp-size: min(76px, calc((100cqh - 3 * var(--sp-3)) / 4));
    --probe: min(76px, calc((100cqh - 3 * var(--sp-3)) / 4));
  }
  .tp-kp-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--sp-3);justify-items:center;align-content:center}
  .tp-kp{width:var(--kp-size);height:var(--kp-size);border-radius:999px;background:#58ABFF;border:none}
</style></head><body>
<div class="tp-viewport"><div class="tp-screen tp-feature">
  <div class="tp-hero"></div>
  <div class="tp-panel"><div class="tp-panel-body"><div class="tp-kp-grid">
    ${Array.from({length:12},(_,i)=>`<button class="tp-kp" data-k="${i}"></button>`).join("")}
  </div></div></div>
</div></div></body></html>`;

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
const rows = [];
for (const [w,h] of VIEWPORTS) {
  const page = await browser.newPage({ viewport:{width:w,height:h}, hasTouch:true, isMobile:true });
  await page.setContent(html);
  rows.push(await page.evaluate((vp) => {
    const q = s => document.querySelector(s);
    const cs = (el,p) => getComputedStyle(el).getPropertyValue(p).trim();
    const panel = q(".tp-panel"), body = q(".tp-panel-body"), hero = q(".tp-hero"), grid = q(".tp-kp-grid");
    const keys = [...document.querySelectorAll(".tp-kp")];
    const pr = panel.getBoundingClientRect(), br = body.getBoundingClientRect();
    const gr = grid.getBoundingClientRect();
    const px = v => Math.round(parseFloat(v)*10)/10;
    return {
      vp,
      u: cs(q(".tp-viewport"),"--u"),
      hero: Math.round(hero.getBoundingClientRect().height*10)/10,
      panel: Math.round(pr.height*10)/10,
      contentBox: Math.round((panel.clientHeight - parseFloat(getComputedStyle(panel).paddingTop) - parseFloat(getComputedStyle(panel).paddingBottom))*10)/10,
      kp_CORRECT: px(cs(body,"--probe")),
      kp_AS_PUBLISHED: px(cs(panel,"--probe-WRONG")),
      keyBox: Math.round(keys[0].getBoundingClientRect().height*10)/10,
      gridFits: gr.height <= br.height + 0.5,
      gridH: Math.round(gr.height*10)/10,
      bodyH: Math.round(br.height*10)/10,
      lastKeyBottom: Math.round(keys[11].getBoundingClientRect().bottom*10)/10,
      panelBottom: Math.round(pr.bottom*10)/10,
      viewportH: window.innerHeight,
      pastViewport: Math.max(0, Math.round((q(".tp-screen").getBoundingClientRect().bottom - window.innerHeight)*10)/10),
      underDock: Math.max(0, Math.round((keys[11].getBoundingClientRect().bottom - (window.innerHeight - 64))*10)/10),
    };
  }, `${w}x${h}`));
  await page.close();
}
await browser.close();
console.log("vp        u      hero   panel  content  kp(correct) kp(as-published) 4rowsFit  past  underDock");
for (const r of rows) {
  console.log(
    `${r.vp.padEnd(9)} ${String(r.u).padEnd(6)} ${String(r.hero).padEnd(6)} ${String(r.panel).padEnd(6)} ${String(r.contentBox).padEnd(8)} ${String(r.kp_CORRECT).padEnd(11)} ${String(r.kp_AS_PUBLISHED).padEnd(16)} ${String(r.gridFits).padEnd(9)} ${String(r.pastViewport).padEnd(5)} ${r.underDock}`);
}
EOF
