                                {inv.description}
                              </span>
                            )}
                            {isSplit && (
                              <span style={{ marginLeft: 6, fontSize: 10, fontWeight: 700, color: '#1BBF85', background: 'rgba(27,191,133,0.12)', padding: '1px 6px', borderRadius: 6 }}>
                                {paid}/{inv.splitCount} split
