        </button>

        <div style={{ flex: 1 }} />

        <button
          className="tp-cta"
          data-demo-id="trades-invoice-send"
          onClick={onSend}
          disabled={sending || amount <= 0 || !quickOk}
          style={{ minWidth: 220, opacity: sending || amount <= 0 || !quickOk ? 0.65 : 1, flexShrink: 0 }}
