    const velocity = dy / elapsed;
    const progress = rubber(dy / SWIPE_TRAVEL);
    endGesture(progress > EXPAND_THRESHOLD || velocity > FLICK_VELOCITY);
  };
  const onHandlePointerCancel = () => endGesture(null);

