57	    { id: "home", path: "/dashboard", Icon: IcoHome },
58	    { id: "stock", path: "/stock", Icon: IcoBox },
59	    { id: "terminal", path: "/terminal", Icon: IcoTerminal },
60	    { id: "analytics", path: "/transactions", Icon: IcoAnalytics },
61	    { id: "settings", path: "/settings", Icon: IcoSettings },
62	  ],
63	  property: [
64	    { id: "home", path: "/property", Icon: IcoHome },
65	    { id: "tenants", path: "/property/tenants", Icon: IcoPerson },
66	    { id: "terminal", path: "/property/terminal", Icon: IcoTerminal },
67	    { id: "analytics", path: "/property/analytics", Icon: IcoAnalytics },
68	    { id: "settings", path: "/settings", Icon: IcoSettings },
69	  ],
