79	const initialNavWidth = () => typeof window === "undefined" ? 320 : Math.min(320, window.innerWidth - 32);
80	
81	/* docs/SPEC-2026-08-20-dock-implementation.md §7.3. Linear up to full travel,
82	   then asymptotic to 1.32 — 56px of overshoot yields ~12px of extra visual
83	   movement and the dock never detaches from the finger. */
84	const rubber = (p: number) => (p <= 1 ? Math.max(0, p) : 1 + (1 - Math.exp(-(p - 1) * 0.55)) * 0.32);
85	const clamp01 = (n: number) => Math.max(0, Math.min(1, n));
86	
87	const SWIPE_TRAVEL = 56; // px of drag that maps to progress 1.0
88	const EXPAND_THRESHOLD = 0.45;
89	const FLICK_VELOCITY = 0.4; // px/ms
90	const TAP_SLOP = 6; // px — below this a body pointerdown is still a tap, not a drag
91	
92	export function TerminalDockView({ mode, activeId, onPick, placement = "fixed", collapseAfterMs = 4_000, collapse = "auto" }: TerminalDockViewProps) {
93	  const items = TERMINAL_DOCK_ITEMS[mode];
94	  const activeIdx = items.findIndex((item) => item.id === activeId);
95	  const navRef = useRef<HTMLElement>(null);
96	  const dockRef = useRef<HTMLDivElement>(null);
97	  const handleRef = useRef<HTMLButtonElement>(null);
98	  const btnRefs = useRef<(HTMLButtonElement | null)[]>([]);
99	  const mounted = useRef(false);
100	  const idleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
101	  const [indLeft, setIndLeft] = useState(0);
102	  const [animating, setAnimating] = useState(false);
103	  const [collapsed, setCollapsed] = useState(false);
104	  const [navWidth, setNavWidth] = useState(initialNavWidth);
105	
106	  /* Gesture state. Refs for the per-frame math (no re-render needed until the
107	     visual progress actually changes); dragT is the one piece read by render. */
108	  const gesture = useRef<{ kind: "expand" | "collapse"; x0: number; y0: number; t0: number; crossedSlop: boolean } | null>(null);
109	  const [dragT, setDragT] = useState<number | null>(null); // null = not dragging
110	
111	  useEffect(() => {
112	    const onResize = () => setNavWidth(Math.min(320, window.innerWidth - 32));
113	    window.addEventListener("resize", onResize);
114	    return () => window.removeEventListener("resize", onResize);
115	  }, []);
116	
117	  /* Phase A of docs/PLAN-2026-08-17-terminal-panels-and-dock.md: publish the
118	     dock's real footprint so every screen reserves the same number instead of
119	     the six hand-tuned literals in §1.2.
120	
121	     It goes on `document.documentElement` deliberately. App.tsx renders
122	     <Router /> and <BottomNavigation /> as siblings, so a terminal-scoped
123	     write is invisible to the dock and a dock-scoped one is invisible to the
124	     terminal — the variable would silently resolve to its initial value on
125	     exactly the screens that need it.
126	
127	     Only the fixed placement publishes. The landing page's phone demo mounts
128	     this dock with placement="absolute" inside a scaled mock; its height is not
129	     the real chrome and must not become the app's reservation (§4.3 clause 9). */
130	  useEffect(() => {
131	    if (placement !== "fixed") return;
132	    const nav = navRef.current;
133	    if (!nav || typeof document === "undefined") return;
134	    const root = document.documentElement;
135	
136	    const publish = () => {
137	      const { height } = nav.getBoundingClientRect();
138	      root.style.setProperty("--dock-h", `${Math.round(height * 100) / 100}px`);
139	    };
140	    publish();
141	
142	    /* The wrapper's height is transitioned, so this fires per frame during a
143	       collapse and the token tracks it rather than jumping at the end. */
144	    const observer =
145	      typeof ResizeObserver === "undefined" ? null : new ResizeObserver(publish);
146	    observer?.observe(nav);
147	
148	    return () => {
149	      observer?.disconnect();
150	      /* Cleared, not left stale: a screen rendered with no dock must not go on
151	         reserving space for one. */
152	      root.style.removeProperty("--dock-h");
153	    };
154	  }, [placement]);
155	
156	  const calcLeft = (idx: number) => {
157	    const button = btnRefs.current[Math.max(0, idx)];
158	    const dock = dockRef.current;
159	    if (!button || !dock) return indLeft;
160	    const buttonRect = button.getBoundingClientRect();
161	    const dockRect = dock.getBoundingClientRect();
162	    return buttonRect.left - dockRect.left + buttonRect.width / 2 - 32.5;
163	  };
164	
165	  useEffect(() => {
166	    const idx = Math.max(0, activeIdx);
167	    if (!mounted.current) {
168	      setIndLeft(calcLeft(idx));
169	      requestAnimationFrame(() => { mounted.current = true; });
170	      return;
171	    }
172	    setAnimating(true);
173	    setIndLeft(calcLeft(idx));
174	    const timer = setTimeout(() => setAnimating(false), 550);
175	    return () => clearTimeout(timer);
176	  }, [activeId, mode]);
177	
178	  /* Phase D. `collapse` is a request from the terminal (via the store) or
179	     "auto" for the idle-timer behaviour this dock has always had. Either way,
180	     a route/mode change re-asserts the requested state — that is intent, not
181	     a stray touch, and it is the only thing (besides a swipe) allowed to move
182	     `collapsed` once E lands. */
183	  useEffect(() => {
184	    if (idleTimer.current) { clearTimeout(idleTimer.current); idleTimer.current = null; }
185	    if (collapse === "collapsed") { setCollapsed(true); return; }
186	    if (collapse === "expanded") { setCollapsed(false); return; }
187	    setCollapsed(false);
188	    if (collapseAfterMs !== null) idleTimer.current = setTimeout(() => setCollapsed(true), collapseAfterMs);
189	  }, [collapse, activeId, mode, collapseAfterMs]);
190	
191	  useEffect(() => () => { if (idleTimer.current) clearTimeout(idleTimer.current); }, []);
192	
193	  /* ── Phase E: the swipe. Track the gesture, don't detect it — pointer
194	     events + touch-action: none + transition: dragging ? 'none' : '…', the
195	     idiom already used at transactions.tsx:512-518,
196	     property-analytics.tsx:309-313, trades-analytics.tsx:317-321. ── */
197	
198	  const endGesture = (expand: boolean | null) => {
199	    gesture.current = null;
200	    setDragT(null);
201	    if (expand === true) setCollapsed(false);
202	    else if (expand === false) setCollapsed(true);
203	    // null = settle back to whatever `collapsed` already was (aborted/cancelled)
204	  };
205	
206	  const onHandlePointerDown = (event: React.PointerEvent<HTMLButtonElement>) => {
207	    if (!collapsed) return;
208	    handleRef.current?.setPointerCapture(event.pointerId);
209	    gesture.current = { kind: "expand", x0: event.clientX, y0: event.clientY, t0: event.timeStamp, crossedSlop: true };
210	    setDragT(0);
211	  };
212	  const onHandlePointerMove = (event: React.PointerEvent<HTMLButtonElement>) => {
213	    const g = gesture.current;
214	    if (!g || g.kind !== "expand") return;
215	    const dy = g.y0 - event.clientY;
216	    const dx = event.clientX - g.x0;
217	    if (Math.abs(dx) > Math.abs(dy) + 8) { endGesture(null); return; } // sideways — not this gesture
218	    setDragT(rubber(dy / SWIPE_TRAVEL));
219	  };
220	  const onHandlePointerUp = (event: React.PointerEvent<HTMLButtonElement>) => {
221	    const g = gesture.current;
222	    if (!g || g.kind !== "expand") return;
223	    const dy = g.y0 - event.clientY;
224	    const elapsed = Math.max(1, event.timeStamp - g.t0);
225	    const velocity = dy / elapsed;
226	    const progress = rubber(dy / SWIPE_TRAVEL);
227	    endGesture(progress > EXPAND_THRESHOLD || velocity > FLICK_VELOCITY);
228	  };
229	  const onHandlePointerCancel = () => endGesture(null);
230	
231	  /* A keyboard activation dispatches a click with detail === 0; a pointer tap
232	     is detail >= 1. The tap path is owned entirely by the drag lifecycle
233	     above (a tap yields ~0 progress, which resolves to "stay collapsed") —
234	     this handler exists only for the keyboard/AT path. */
235	  const onHandleClick = (event: React.MouseEvent<HTMLButtonElement>) => {
236	    if (event.detail !== 0) return;
237	    setCollapsed(false);
238	  };
239	
240	  /* Downward swipe on the expanded dock body collapses it again (§7.5). A tap
241	     on an icon must keep working: nothing is captured or prevented until the
242	     drag actually crosses TAP_SLOP, so a plain tap's click reaches the button
243	     under the finger completely untouched. */
244	  const onBodyPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
245	    if (collapsed) return;
246	    gesture.current = { kind: "collapse", x0: event.clientX, y0: event.clientY, t0: event.timeStamp, crossedSlop: false };
247	  };
248	  const onBodyPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
249	    const g = gesture.current;
250	    if (!g || g.kind !== "collapse") return;
251	    const dy = event.clientY - g.y0;
252	    const dx = event.clientX - g.x0;
253	    if (!g.crossedSlop) {
254	      if (Math.hypot(dx, dy) < TAP_SLOP) return; // still might be a tap — do nothing yet
255	      if (Math.abs(dx) > Math.abs(dy)) { gesture.current = null; return; } // sideways — let it be whatever it is
256	      g.crossedSlop = true;
257	      dockRef.current?.setPointerCapture(event.pointerId);
258	    }
259	    event.preventDefault();
260	    setDragT(rubber(dy / SWIPE_TRAVEL));
261	  };
262	  const onBodyPointerUp = (event: React.PointerEvent<HTMLDivElement>) => {
263	    const g = gesture.current;
264	    if (!g || g.kind !== "collapse") { gesture.current = null; return; }
265	    if (!g.crossedSlop) { gesture.current = null; return; } // a tap — let the button's own onClick handle it
266	    const dy = event.clientY - g.y0;
267	    const elapsed = Math.max(1, event.timeStamp - g.t0);
268	    const velocity = dy / elapsed;
269	    const progress = rubber(dy / SWIPE_TRAVEL);
270	    endGesture(!(progress > EXPAND_THRESHOLD || velocity > FLICK_VELOCITY));
271	  };
272	  const onBodyPointerCancel = () => { gesture.current = null; endGesture(null); };
273	  /* A drag that crossed the slop must not also fire the icon button's click
274	     underneath it — capture-phase so it runs before the button's own onClick. */
275	  const onBodyClickCapture = (event: React.MouseEvent<HTMLDivElement>) => {
276	    if (gesture.current?.kind === "collapse" && gesture.current.crossedSlop) event.stopPropagation();
277	  };
278	
279	  const dragging = dragT !== null;
280	  const restT = collapsed ? 1 : 0;
281	  const visualT = dragging ? clamp01(gesture.current?.kind === "expand" ? 1 - (dragT as number) : (dragT as number)) : restT;
282	  const dragCurve = dragging ? "none" : undefined;
283	
284	  const palette = mode === "trades"
285	    ? { dock: TRADES_DOCK, active: TRADES_ACTIVE, dim: TRADES_DIM }
286	    : { dock: DOCK_BG, active: BLUE, dim: BLUE_DIM };
287	
288	  return (
289	    <nav ref={navRef} aria-label="Merchant navigation" data-demo-id="terminal-dock" data-terminal-dock-mode={mode} style={{ position: placement, bottom: 0, left: 0, right: 0, display: "flex", justifyContent: "center", paddingBottom: "max(20px, env(safe-area-inset-bottom, 20px))", zIndex: 60, pointerEvents: "none" }}>
290	      <div style={{ position: "relative", width: navWidth, height: 58 - 14 * visualT, display: "flex", alignItems: "center", justifyContent: "center", pointerEvents: "auto", transition: dragCurve ?? "height 0.5s cubic-bezier(0.34,1.56,0.64,1)", overflow: "visible" }}>
291	        <button
292	          ref={handleRef}
293	          type="button"
294	          aria-expanded={!collapsed}
295	          aria-label="show navigation"
296	          data-demo-id="dock-handle"
297	          onPointerDown={onHandlePointerDown}
298	          onPointerMove={onHandlePointerMove}
299	          onPointerUp={onHandlePointerUp}
300	          onPointerCancel={onHandlePointerCancel}
301	          onClick={onHandleClick}
302	          style={{
303	            position: "absolute", bottom: 0, left: "50%", transform: "translateX(-50%)",
304	            width: 120, height: 36, padding: 0, margin: 0, border: "none", background: "none",
305	            display: "flex", alignItems: "flex-end", justifyContent: "center", paddingBottom: 10,
306	            touchAction: "none", cursor: collapsed ? "grab" : "default",
307	            pointerEvents: collapsed ? "auto" : "none",
308	            WebkitTapHighlightColor: "transparent",
309	          }}
310	        >
311	          <span aria-hidden="true" style={{ width: 56 * visualT, height: Math.max(4, 4 * visualT), background: palette.dock, borderRadius: 999, opacity: visualT, transition: dragCurve ?? "width 0.45s cubic-bezier(0.34,1.56,0.64,1), opacity 0.3s ease", pointerEvents: "none" }} />
312	        </button>
313	        <div
314	          ref={dockRef}
315	          onPointerDown={onBodyPointerDown}
316	          onPointerMove={onBodyPointerMove}
317	          onPointerUp={onBodyPointerUp}
318	          onPointerCancel={onBodyPointerCancel}
319	          onClickCapture={onBodyClickCapture}
320	          style={{ position: "relative", width: 280, height: 48, background: palette.dock, borderRadius: 24, display: "flex", alignItems: "center", justifyContent: "space-around", padding: "0 16px", overflow: "visible", opacity: 1 - visualT, transform: `scale(${1 - 0.15 * visualT})`, transition: dragCurve ?? "opacity 0.3s ease, transform 0.45s cubic-bezier(0.34,1.56,0.64,1)", pointerEvents: visualT < 0.5 ? "auto" : "none" }}
321	        >
322	          <div aria-hidden="true" style={{ position: "absolute", left: indLeft, top: -5, width: 65, height: 58, background: palette.dock, borderRadius: 29, boxShadow: "0 4px 20px rgba(0,0,0,0.45)", pointerEvents: "none", willChange: "left", transition: animating ? "left 0.45s cubic-bezier(0.34,1.56,0.64,1)" : "none", zIndex: 0 }} />
323	          {items.map(({ id, path, Icon }, index) => {
324	            const isActive = index === activeIdx;
325	            return <button key={id} ref={(element) => { btnRefs.current[index] = element; }} type="button" onClick={() => onPick({ id, path })} aria-label={id} aria-current={isActive ? "page" : undefined} data-demo-id={`dock-${id}`} style={{ position: "relative", zIndex: 1, background: "none", border: "none", padding: 8, cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center", transform: isActive ? "scale(1.15)" : "scale(1)", transition: "transform 0.25s ease", WebkitTapHighlightColor: "transparent" }}><Icon c={isActive ? palette.active : palette.dim} /></button>;
326	          })}
327	        </div>
328	      </div>
329	    </nav>
330	  );
331	}
