import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "./scripts/desktop-shots/retail-fixtures.mjs";

const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
const { context, page } = await newRetailPage(browser, "goo-probe", { viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
await page.goto(`${BASE_URL}/dashboard`, { waitUntil: "domcontentloaded" });
await page.locator('nav[data-demo-id="terminal-dock"]').waitFor({ state: "visible", timeout: 20000 });
await page.waitForTimeout(500);

const restBefore = await page.evaluate(() => {
  const goo = document.querySelector('[data-demo-id="dock-goo"]');
  return { present: !!goo, filter: goo ? getComputedStyle(goo).filter : null };
});

// Force an idle collapse quickly by shortening nothing — instead drive via the
// exposed collapseAfterMs default (4000ms) is too slow for a probe; simulate
// by dispatching a synthetic swipe-independent path: read whether morphing
// mounts the goo layer mid-animation by polling right after a route change
// (Phase D use --dock-h didn't change on /dashboard, it's a .tp-home route
// outside the terminal, so instead drive the /terminal route's screen change).
await page.goto(`${BASE_URL}/terminal`, { waitUntil: "domcontentloaded" });
await page.locator(".tp-viewport").waitFor({ state: "visible", timeout: 20000 });
await page.waitForTimeout(500);

// Navigate into a feature screen to trigger Phase D's programmatic collapse,
// which should trigger the Phase F morph (animate=true path).
await page.getByRole("button", { name: "add item", exact: true }).click();

// Sample repeatedly over the next 600ms to try to catch the morph mid-flight.
const samples = [];
for (let i = 0; i < 12; i++) {
  const s = await page.evaluate(() => {
    const goo = document.querySelector('[data-demo-id="dock-goo"]');
    const dockH = getComputedStyle(document.documentElement).getPropertyValue('--dock-h').trim();
    return { present: !!goo, filter: goo ? getComputedStyle(goo).filter : null, dockH };
  });
  samples.push(s);
  await page.waitForTimeout(50);
}

const restAfter = await page.evaluate(() => {
  const goo = document.querySelector('[data-demo-id="dock-goo"]');
  return { present: !!goo, filter: goo ? getComputedStyle(goo).filter : null };
});

console.log(JSON.stringify({ restBefore, samples, restAfter }, null, 2));
await context.close();
await browser.close();
EOF
